sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 center;
uniform float sweep;
uniform float style;
half4 main(float2 coord) {
    float2 c = center * size;
    float span = radians(sweep);
    if (span <= 0.0) return image.eval(coord);
    float2 d = coord - c;
    float2 lo = style > 0.5 ? screen.xy + 0.5 : float2(-1e9);
    float2 hi = style > 0.5 ? screen.xy + screen.zw - 0.5 : float2(1e9);
    half4 sum = half4(0.0);
    for (int i = 0; i < 48; i++) {
        float a = span * (float(i) / 47.0 - 0.5);
        sum += image.eval(clamp(c + float2(cos(a) * d.x - sin(a) * d.y, sin(a) * d.x + cos(a) * d.y), lo, hi));
    }
    return sum / 48.0;
}
